/* eslint-disable no-unused-vars */
import React, { useEffect, useMemo, useRef, useState } from 'react';
import type { KidsZone } from '../types/kidsStory';

// Ensures this file is treated as a module under `isolatedModules` in CRA/Babel builds.
export {};

type Zone01 = {
  id: string;
  x: number; // 0..1 (center)
  y: number; // 0..1 (center)
  width: number; // 0..1
  height: number; // 0..1
  radius?: number;
  audioCueId: string;
  ttsKey?: string;
};

type Props = {
  zones: KidsZone[];
  // Visible image rect (in px) relative to the scene wrap.
  // We need it to translate pointer positions => normalized coords.
  imageRectPx: { left: number; top: number; width: number; height: number };
  onChange: (zones: Zone01[]) => void;
};

function clamp(v: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, v));
}

function to01(v: number): number {
  // Backward compatibility for story.json that may still use 0..100.
  const n = v > 1.001 ? v / 100 : v;
  return clamp(n, 0, 1);
}

function zoneTo01(z: KidsZone): Zone01 {
  return {
    id: z.id,
    x: to01(z.x),
    y: to01(z.y),
    width: to01(z.width),
    height: to01(z.height),
    radius: z.radius,
    audioCueId: z.audioCueId,
    ttsKey: z.ttsKey,
  };
}

type DragMode =
  | { type: 'none' }
  | { type: 'move'; zoneId: string; startPointer: { x: number; y: number }; startZone: Zone01 }
  | {
      type: 'resize';
      zoneId: string;
      handle: 'nw' | 'ne' | 'se' | 'sw';
      startPointer: { x: number; y: number };
      startZone: Zone01;
    };

function pxToNorm(pointPx: { x: number; y: number }, rect: Props['imageRectPx']): { x: number; y: number } {
  // Convert absolute px coords (relative to scene wrap) => 0..1 inside image rect
  const x = (pointPx.x - rect.left) / rect.width;
  const y = (pointPx.y - rect.top) / rect.height;
  return { x: clamp(x, 0, 1), y: clamp(y, 0, 1) };
}

function normToStyle(zone: Zone01): React.CSSProperties {
  return {
    left: `${zone.x * 100}%`,
    top: `${zone.y * 100}%`,
    width: `${zone.width * 100}%`,
    height: `${zone.height * 100}%`,
    transform: 'translate(-50%, -50%)',
    borderRadius: `${clamp(zone.radius ?? 0, 0, 50)}%`,
  };
}

export default function ZoneEditorOverlay({ zones, imageRectPx, onChange }: Props) {
  const [localZones, setLocalZones] = useState<Zone01[]>(() => zones.map(zoneTo01));
  const [selectedId, setSelectedId] = useState<string | null>(() => (zones[0]?.id ? zones[0].id : null));

  const dragRef = useRef<DragMode>({ type: 'none' });

  useEffect(() => {
    // If scene changes, refresh local zones
    setLocalZones(zones.map(zoneTo01));
    setSelectedId(zones[0]?.id ? zones[0].id : null);
  }, [zones]);

  useEffect(() => {
    onChange(localZones);
  }, [localZones, onChange]);

  const selectedZone = useMemo(() => localZones.find((z) => z.id === selectedId) ?? null, [localZones, selectedId]);

  const onPointerDownZone: React.PointerEventHandler<HTMLDivElement> = (e) => {
