        }
        if (drag.handle === 'ne') {
          right = moveCorner.x;
          top = moveCorner.y;
        }
        if (drag.handle === 'se') {
          right = moveCorner.x;
          bottom = moveCorner.y;
        }
        if (drag.handle === 'sw') {
